//! Modbus Organization, "MODBUS Messaging on TCP/IP Implementation Guide" v1.0b
//! §4.1: the MBAP header is a 16-bit transaction identifier, a 16-bit protocol
//! identifier that is zero for Modbus, a 16-bit length counting the unit
//! identifier and everything after it, and a one-octet unit identifier. The
//! function code is the first octet of the PDU that follows and is named here
//! because it is what a filter asks for.
//!
//! Generated by dev/protogen from dev/protogen/specs/modbus.toml. Field layouts
//! come from the RFC cited above; edit the spec, not this file.

use crate::field::FieldDesc;
use crate::proto::{ProtoDesc, ProtoId};

// protogen:hand begin
/// §4.1: Length counts the unit identifier and the PDU after it.
fn content_len(hdr: &[u8]) -> usize {
    match hdr.get(4..6) {
        Some(b) => 6 + u16::from_be_bytes([b[0], b[1]]) as usize,
        None => 0,
    }
}

/// The protocol identifier is zero for Modbus, which is what separates a
/// message boundary from the middle of a stream.
pub fn looks_like(p: &[u8]) -> bool {
    p.len() >= 8 && p[2] == 0 && p[3] == 0
}
// protogen:hand end

pub static FIELDS: &[FieldDesc] = &[
    FieldDesc::uint("transId", 0, 16, 0),
    FieldDesc::uint("protoId", 16, 16, 0),
    FieldDesc::uint("len", 32, 16, 2),
    FieldDesc::uint("unitId", 48, 8, 0),
    FieldDesc::uint("funcCode", 56, 8, 3),
];

fn header_len(_: &[u8]) -> usize {
    8
}

pub static DESC: ProtoDesc = ProtoDesc {
    id: ProtoId::Modbus,
    name: "ModbusADU",
    fields: FIELDS,
    min_len: 8,
    header_len,
    next: crate::proto::next_raw,
    build_len: 8,
    parse_options: None,
    opt_table: None,
    set_hlen: None,
    bind_next: None,
    bind_next_bytes: None,
    content_len: Some(content_len),
};

#[cfg(test)]
mod tests {
    #![allow(unused_imports)]
    use super::*;
    use crate::field::FieldValue;
    use crate::packet::Packet;

    // protogen:tests begin
    /// Modbus TCP read holding registers: transaction 1, protocol 0, length 6, unit 1, function 3, address 0, count 1.
    fn vector() -> Vec<u8> {
        vec![
            0x00, 0x01, 0x00, 0x00, 0x00, 0x06, 0x01, 0x03, 0x00, 0x00, 0x00, 0x01,
        ]
    }

    #[test]
    fn dissects_the_rfc_vector() {
        let p = Packet::dissect(vector(), ProtoId::Modbus);
        let l = p.find_layer(ProtoId::Modbus).unwrap();
        assert_eq!(p.get(l, "transId").unwrap(), FieldValue::Uint(1));
        assert_eq!(p.get(l, "protoId").unwrap(), FieldValue::Uint(0));
        assert_eq!(p.get(l, "len").unwrap(), FieldValue::Uint(6));
        assert_eq!(p.get(l, "unitId").unwrap(), FieldValue::Uint(1));
        assert_eq!(p.get(l, "funcCode").unwrap(), FieldValue::Uint(3));
        assert_eq!(p.raw_bytes(), &vector()[..]);
    }

    #[test]
    fn truncation_does_not_panic() {
        for n in 0..vector().len() {
            let p = Packet::dissect(vector()[..n].to_vec(), ProtoId::Modbus);
            assert_eq!(p.raw_bytes(), &vector()[..n]);
        }
    }

    #[test]
    fn writes_survive_a_rebuild() {
        let mut p = Packet::dissect(vector(), ProtoId::Modbus);
        let l = p.find_layer(ProtoId::Modbus).unwrap();
        let n = p.raw_bytes().len();
        for f in crate::proto::active_fields(ProtoId::Modbus, p.header(l))
            .filter(|f| f.kind == crate::field::FieldKind::Uint && f.bit_len <= 32)
            .map(|f| f.name)
            .collect::<Vec<_>>()
        {
            p.set_uint(l, f, 1);
        }
        assert_eq!(p.to_bytes().len(), n);
    }
    // protogen:tests end
}
